const MAX_OPS=48u; struct Instr{op:u32,a:i32,b:i32,c:i32,k0:f32,k1:f32,k2:f32,pad:f32}; struct Genome{seed:u32,kind:u32,nOps:u32,root:u32,pal:array<vec4f,4>}; @group(0)@binding(2) var<storage,read> prog:array<Instr>; @group(0)@binding(3) var<storage,read> gen:array<Genome>; @group(0)@binding(4) var<uniform> P:Params; // P.tileId, P.time
fn scrub(v:vec4f)->vec4f{ return select(v,vec4f(0.0),v!=v); }
fn sdiv(a:f32,b:f32)->f32{ return a/(b+select(1e-6,-1e-6,b<0.0)); }
// UNIFORM full-length loop, topo order => no stack, no recursion, no divergence
fn evalGenome(gi:u32,p:vec2f,t:f32)->vec4f{
  let base=gi*MAX_OPS; let g=gen[gi];
  var reg:array<vec4f,48>;
  for(var i:u32=0u;i<MAX_OPS;i=i+1u){
    let ins=prog[base+i];
    let A=reg[u32(max(ins.a,0))]; let B=reg[u32(max(ins.b,0))]; let C=reg[u32(max(ins.c,0))];
    var r=vec4f(0.0);
    switch(ins.op){
      case 0u:{ r=vec4f(ins.k0); }                                   // CONST/NOP
      case 1u:{ r=vec4f(p.x,p.y,t,0.0); }                             // COORD(+time)
      case 2u:{ r=vec4f(length(p),0.0,0.0,0.0); }                     // DIST_CENTER
      case 10u:{ r=vec4f(fbm(A.x*ins.k0,A.y*ins.k0,i32(g.seed)+ins.a*13,i32(clamp(ins.k1,1.0,6.0)),1.0)); } // FBM
      case 11u:{ r=vec4f(ridge(A.x*ins.k0,A.y*ins.k0,i32(g.seed)+ins.a*13,i32(clamp(ins.k1,1.0,6.0)),1.0)); } // RIDGE
      case 12u:{ let w=worley2(A.xy*ins.k0,i32(g.seed)); r=vec4f(w,w.y-w.x,0.0); } // WORLEY F1,F2,edge
      case 20u:{ let q=fbm(A.x+5.2,A.y+1.3,i32(g.seed)+7,4,ins.k1); r=vec4f(A.xy+(vec2f(A.x,q)-0.5)*2.0*ins.k0,0.0,0.0); } // DOMAIN_WARP -> coords
      case 21u:{ let an=atan2(A.y,A.x); let rr=length(A.xy); let sg=6.2831853/max(ins.k0,1.0); let fa=abs(an-floor(an/sg+0.5)*sg); r=vec4f(cos(fa),sin(fa),0.0,0.0)*rr; } // RADIAL
      case 30u:{ r=A+B; } case 31u:{ r=A-B; } case 32u:{ r=A*B; }
      case 33u:{ r=mix(A,B,clamp(C.x,0.0,1.0)); }                     // MIX by field
      case 34u:{ r=min(A,B); } case 35u:{ r=max(A,B); }
      case 36u:{ let k=max(ins.k0,1e-3); let h=clamp(0.5+0.5*(B.x-A.x)/k,0.0,1.0); r=vec4f(mix(B.x,A.x,h)-k*h*(1.0-h)); } // SMOOTHMIN
      case 38u:{ r=vec4f(smoothstep(ins.k0,ins.k1,A.x)); }            // SMOOTHBAND
      case 40u:{ r=vec4f((floor(A.x*ins.k0)+pow(fract(A.x*ins.k0),max(ins.k1,1e-3)))/ins.k0); } // TERRACE
      case 41u:{ r=vec4f(pow(clamp(A.x,0.0,1.0),max(ins.k0,1e-3))); } // POW
      case 42u:{ r=vec4f(step(ins.k0,A.x)); }                         // THRESHOLD
      case 43u:{ r=vec4f(sin(t*ins.k0)*0.5+0.5); }                    // PULSE
      // ---- INTERPRET ROOTS (chosen by g.kind) ----
      case 70u:{ r=vec4f(ins.k1+(A.x-0.5)*2.0*ins.k0); }             // AS_HEIGHT
      case 71u:{ r=vec4f(max(smoothstep(1.0-ins.k0,1.0,A.x),0.0)); } // AS_DENSITY
      case 72u:{ r=vec4f(g.pal[0].xyz+g.pal[1].xyz*cos(6.2831853*(g.pal[2].xyz*A.x+g.pal[3].xyz)),1.0); } // AS_COLOR (IQ palette)
      case 73u:{ let e=0.01; let n1=fbm(A.x,A.y+e,733,4,1.0); let n2=fbm(A.x,A.y-e,733,4,1.0); let n3=fbm(A.x+e,A.y,733,4,1.0); let n4=fbm(A.x-e,A.y,733,4,1.0); r=vec4f(normalize(vec2f((n1-n2),-(n3-n4))+1e-6),0.0,0.0); } // AS_FLOW
      case 75u:{ r=vec4f(g.pal[0].xyz*pow(clamp(A.x,0.0,1.0),3.0)*(0.6+0.4*(sin(t*2.0)*0.5+0.5)),1.0); } // AS_EMISSIVE
      default:{ r=A; }
    }
    reg[i]=select(vec4f(0.0),scrub(r),i<g.nOps);  // mask inactive slots -> uniform flow
  }
  return reg[g.root];
}
